    private void botonactualizarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_botonactualizarActionPerformed
    
    try {
        ControladorMascota controlador = new ControladorMascota();
        Mascota mascota = new Mascota(
            Integer.parseInt(txtidmascota.getText()),
            txtnombre.getText(),
            txtespecie.getText(),
            txtraza.getText(),
            Double.parseDouble(txtpeso.getText()), // CORREGIDO
            "N/A"

        );
        controlador.actualizarMascota(mascota);
        JOptionPane.showMessageDialog(this, "Mascota actualizada correctamente");
    } catch (Exception e) {
        JOptionPane.showMessageDialog(this, "Error: " + e.getMessage());
    }

    }//GEN-LAST:event_botonactualizarActionPerformed

    private void botoneliminarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_botoneliminarActionPerformed
        
    try {
        ControladorMascota controlador = new ControladorMascota();
        Mascota mascota = controlador.buscarMascotaPorId(Integer.parseInt(txtidmascota.getText()));
        if (mascota != null) {
            controlador.eliminarMascota(mascota);
            JOptionPane.showMessageDialog(this, "Mascota eliminada correctamente");
        } else {
            JOptionPane.showMessageDialog(this, "Mascota no encontrada");
        }
    } catch (Exception e) {
        JOptionPane.showMessageDialog(this, "Error: " + e.getMessage());
    }
    }//GEN-LAST:event_botoneliminarActionPerformed

    private void botonbuscarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_botonbuscarActionPerformed

    try {
        ControladorMascota controlador = new ControladorMascota();
        java.util.List<Mascota> lista = controlador.listarTodasMascotas();

        DefaultTableModel modelo = new DefaultTableModel(new String[]{"ID", "Nombre", "Especie", "Raza", "Peso"}, 0);
        for (Mascota m : lista) {
            modelo.addRow(new Object[]{m.getIdmascota(), m.getNombre(), m.getEspecie(), m.getRaza(), m.getPeso()});
        }
        tablaMascotas.setModel(modelo);
    } catch (Exception e) {
        JOptionPane.showMessageDialog(this, "Error: " + e.getMessage());
    }

    }//GEN-LAST:event_botonbuscarActionPerformed

    private void botonguardarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_botonguardarActionPerformed

    try {
        ControladorMascota controlador = new ControladorMascota();
        Mascota mascota = new Mascota(
            Integer.parseInt(txtidmascota.getText()),
            txtnombre.getText(),
            txtespecie.getText(),
            txtraza.getText(),
            Double.parseDouble(txtpeso.getText()),
            "N/A" // Si no tienes campo sexo en la vista
        );
        controlador.registrarMascota(mascota);
        JOptionPane.showMessageDialog(this, "Mascota registrada correctamente");
    } catch (Exception e) {
        JOptionPane.showMessageDialog(this, "Error: " + e.getMessage());
    }

    }//GEN-LAST:event_botonguardarActionPerformed

